using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class ContinuousFrameSumDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/ContinuousFrameSum.";
    private static Formula V(string s) => F.Id(s);
    private static Formula C(string s, params Formula[] xs) => new Formula.FunctionCall(FormulaIdentifier.Create(s), [.. xs]);
    private static Formula All(string s, Formula t, Formula b) => new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(s), t, b);
    private static Formula Ex(string s, Formula t, Formula b) => new Formula.Bind(FormulaQuantifier.Exists, FormulaIdentifier.Create(s), t, b);
    private static Formula Eq(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.Equal, b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.And, b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Implies, b);
    private static Formula Iff(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Iff, b);
    private static Formula In(Formula a, Formula b) => Seq(a, InMacro, Sp, b);
    private static Formula R => Seq(Mathbb, Grp(V("R")));
    private static Formula Space => V("V");
    private static Formula Cone => V("C");
    private static Formula Unit => V("u");
    private static Formula P => C("pure", Cone, Unit);
    private static Formula K => C("base", Cone, Unit);
    private static Formula B => C("exclusionBalls", Cone, Unit);
    private static Formula W => C("weakPair", Cone, Unit);
    private static Formula G => C("commonCenter", V("hB"));
    private static Formula S(Formula p) => C("sumVector", V("hB"), p);
    private static Formula Orth(Formula p, Formula q) => C("excludes", Cone, Unit, p, q);
    private static Formula Context(Formula body) => All("V", V("Type"), Seq(
        OpenBracket, C("NormedAddCommGroup", Space), CloseBracket, Sp,
        OpenBracket, C("NormedSpace", R, Space), CloseBracket, Sp,
        OpenBracket, C("FiniteDimensional", R, Space), CloseBracket, Sp,
        OpenBracket, C("Nontrivial", Space), CloseBracket, Sp,
        All("C", C("PointedCone", R, Space),
        All("u", C("LinearMap", R, Space, R),
        Imp(C("IsClosed", Cone), Imp(All("x",Space,Imp(In(V("x"),Cone),
        Imp(new Formula.Relation(V("x"),FormulaRelationOperator.NotEqual,D(0)),
        new Formula.Relation(D(0),FormulaRelationOperator.LessThan,C("apply",Unit,V("x")))))),
        Imp(Eq(C("span", R, Cone), C("top")), All("hB", B, body))))))));

    public DocumentDefinition Create()
    {
        Formula p = V("p"), q = V("q"), cap = V("U");
        Formula value = All("p", P, Eq(S(p),cap));
        Formula constant = Ex("U", Space, value);
        Formula ri = In(C("smul", C("div", D(1), D(3)), cap), C("intrinsicInterior", R, K));
        Formula interior = In(cap,C("interior",Cone));
        Formula a = Context(Imp(G,And(W,Ex("U",Space,And(value,And(ri,interior))))));
        Formula edge = All("p",P,All("q",P,Imp(Orth(p,q),Eq(S(p),S(q)))));
        Formula orthogonalPairs = Seq(OpenBrace,V("s"),Colon,P,Times,P,Mid,
            Orth(C("fst",V("s")),C("snd",V("s"))),CloseBrace);
        Formula closed = C("IsClosed",orthogonalPairs);
        Formula weakConsequences = And(closed,
            And(C("Continuous",C("sumVector",V("hB"))),And(edge,Iff(G,constant))));
        Formula b = Context(And(Imp(W,weakConsequences),Imp(C("pairProper",Cone,Unit),G)));
        Formula compact = Context(Imp(W,C("IsCompact",P)));
        Formula definitions = And(
            Eq(K,C("normalizedConeBase",Cone,Unit)),
            And(Eq(P,C("extremePoints",R,K)),And(
                Eq(C("center",V("hB"),p),C("apply",C("chosenExclusionChart",V("hB"),p),D(0))),
                Eq(S(p),C("add",p,C("smul",D(2),C("center",V("hB"),p)))))));
        return DocumentDefinition.Create(ScribeNode.Create(
            "Original EB and common centers force weakPair and interior; original W supplies compact pure points and continuous frame sums.",
            H("Original common centers and continuous frame sums"),Blocks(
        Describe.Lean(DescribeId.Create("orthogonal-center-sum"),DeclarationHandle.Create("D5/S3/Quantum/Foundation/ContinuousFrameSum.orthogonal_center_sum"),H("The same original zero-one effect selects antipodes"),StatementSource.WithoutFormula(),AssessedProvenance.FromRepo(),Blocks(Paragraph(Text("For every original closed pointed generating cone with strict unit, all original full effects and whole-ball exclusions, if original pure q and r lie in the entire D(p) and one original proper effect confirms q and vanishes at r, then q+r=2 center(D(p)). Restriction of that same effect to the whole ball determines the antipodal endpoints. No global exclusion injectivity is required. The reflected-ball equality criterion applies this identity to q and its actual original reflection."))),DescribeRole.Theorem),

                Describe.Lean(DescribeId.Create("effects-compact"), DeclarationHandle.Create(Owner + "effects_compact"), H("Compactness of the full original effect interval"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every finite dimensional real normed V, original pointed cone C and linear unit u, strict positivity of u on nonzero cone vectors and span(C)=top imply compactness of the entire original interval effects(C,u)={f : V toL R : proper(C,u,f)}. The original proof and telescope are unchanged. ExclusionIncidence.exclusion_upper_limit directly consumes this fact to obtain a subsequential limit of actual full-interval confirming effects. Neither Pair nor closedness of the pure carrier is needed."))), DescribeRole.Theorem),
                Paragraph(Text("The original carrier is any nonzero finite-dimensional real V, with closed generating cone C and the same strictly positive unit u. K is the whole normalized base, P is ALL its extreme points and [0,u] is the entire original proper-effect interval. No finite carrier, selected menu, assumed compact P, closed orthogonality, common intersection or positive-extension premise is used.")),
                Describe.Lean(DescribeId.Create("original-centers"),DeclarationHandle.Create(Owner+"sumVector"),H("Original centers and frame carrier"),StatementSource.FromAuthor(Disp(Context(All("p",P,definitions)))),
                    AssessedProvenance.FromRepo(),Blocks(
                        Paragraph(Text("exclusionBalls supplies, at every original pure p, an injective affine parametrization of ALL D_p by a finite Euclidean closed unit ball of positive dimension. center is the image of zero in a chosen such chart. sumVector(p)=p+2 center(p) is the original U(p). commonCenter quantifies equality of these vectors over ALL original pure p,q. The frame-sum argument identifies this chart center with the midpoint of every original orthogonal diameter; no frame-fiber sum is assumed.")),
                        Paragraph(Text("effects uses continuous linear maps to represent the original full proper interval. Every real linear map on finite-dimensional V has its native continuous-linear representation, so this does not restrict the original effects. frames initially permits three arbitrary original states with three full proper effects, delta readings, and their linear-map sum exactly u. Purity of the three states is derived where needed; it is not built into that raw compact frame carrier."))),DescribeRole.Definition),
                Describe.Lean(DescribeId.Create("pure-compact"),DeclarationHandle.Create(Owner+"original_pure_compact"),
                    H("Original W forces compactness of all pure points"),StatementSource.FromAuthor(Disp(compact)),
                    AssessedProvenance.FromRepo(),Blocks(
                        Paragraph(Text("The hypotheses are original closedness, strict positivity, generation, EB_ge1 and weakPair. Pure-point compactness is a conclusion. A generating cone has nonempty interior by the existing affine-span criterion. Choose an interior point v and a ball radius, and evaluate any proper effect at v plus and minus a small unit vector. Nonnegativity at both points bounds its operator norm uniformly by u(v) divided by that small radius. The original proper-effect interval is closed, hence compact by the existing finite-dimensional closed-bounded criterion.")),
                        Paragraph(Text("The full raw-frame constraints are closed in the compact product of three original bases and three entire effect intervals. Joint completion is supplied by OrthogonalJointCompletion.whole_joint_completion on the original all-P domain. It also gives injectivity of p to D_p: after completing p to p,r,s, equal exclusions put both owners into the singleton intersection D_r intersect D_s.")),
                        Paragraph(Text("For a raw frame, consider the exposed one-value face of its first effect. Its other two states are different because another effect distinguishes them. For any two pure points in that one-value face, both other states lie in both exclusions. chart_face_eq makes those exclusions equal, and injectivity makes the two pure points equal. The existing compact-face Krein-Milman result then makes the entire one-value face a singleton, proving the first raw vertex pure. Conversely every original pure point is the first vertex of a raw frame by the original joint theorem. Thus P is precisely a continuous projection of the compact raw-frame set. The conclusion uses the derived purity of raw-frame vertices; compact projection and Krein-Milman are existing library results."))),DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("continuous-frame-sum"),DeclarationHandle.Create(Owner+"original_continuous_frame_sum"),
                    H("Continuity, all original orthogonal edges, and full Pair"),StatementSource.FromAuthor(Disp(b)),
                    AssessedProvenance.FromRepo(),Blocks(
                        Paragraph(Text("On the original P squared the existential proper-effect witness relation is closed. This follows by projecting the closed one-zero evaluation constraints through the compact ENTIRE effect interval, using the existing closed-projection theorem. For two original orthogonal pure points q,r in an entire D_p, native sphere coordinates and the public affine_zero_antipode theorem force their coordinates to be antipodal. Affine midpoint preservation then gives q+r=2 center(p). Applied to an original joint triple, this proves p+q+r=U(p)=U(q), hence constancy on EVERY original orthogonal edge.")),
                        Paragraph(Text("Restrict raw frames to those whose three vertices are original pure points. The derived compactness of P makes this restriction compact. Its first-vertex projection is continuous and surjective onto ALL P. Joint completion and its singleton intersection identify any frame's third point with the original joint third point, so U composed with this projection is exactly the continuous sum of the three vertices. Continuity descends through the existing compact closed-map quotient criterion and quotient continuity theorem. No generic continuity lemma is re-proved or counted as new mathematics, and neither carrier compactness nor fiber sums are additional hypotheses.")),
                        Paragraph(Text("commonCenter is equivalent to a single vector value on ALL P; nonemptiness follows from pure_span and nontriviality. Full Pair gives weakPair because an original orthogonal pair is distinct. Under full Pair, the existing complete proper-face classifier gives H(p,q)=D_s for every distinct original pair. Original zero symmetry places s in both original exclusions, yielding two original orthogonal edges through s. Their equalities give U(p)=U(q). Thus the full-Pair implication uses an actually derived common pure point, rather than assuming a common intersection or a covering law."))),DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("common-center-interior"),DeclarationHandle.Create(Owner+"common_center_interior"),
                    H("EB plus G suffices on the original domain"),StatementSource.FromAuthor(Disp(a)),
                    AssessedProvenance.FromRepo(),Blocks(
                        Paragraph(Text("This theorem assumes only the original cone data, EB_ge1 and commonCenter. weakPair is a CONCLUSION. Every U(p) equals one U, and w=U/3 is an original state because w=(p+2 center(p))/3. If w were outside the cone interior, the existing Hahn-Banach support theorem would supply a nonzero linear functional maximizing there. Cone scaling forces its maximum to be zero. Every original p and center(p) then has nonpositive value; the common-center equation forces the value of every p to be zero. Since ALL original pure points span V, the functional is zero, a contradiction. Hence w is in the cone interior; positive scaling gives U in the cone interior. Restricting an open cone neighborhood to the affine span of the normalized base gives w in its intrinsic, or relative, interior.")),
                        Paragraph(Text("For an original p orthogonal to q, take q's antipode r in ALL D_p. Its purity follows from the original exclusion faciality and the sphere extreme-point image theorem. Choose an original common zero confirmer a_q from the EB face theorem. G gives a_q(U)=1, original zero symmetry gives a_q(p)=0, and the antipodal affine identity U=p+q+r gives a_q(r)=0. Thus r belongs to BOTH D_p and D_q. Zero symmetry puts p,q in D_r. The native cone-face lift of D_r now contains their whole original minimal face, which is therefore proper. This proves weakPair directly, without first invoking W.")),
                        Paragraph(Text("Together these declarations cover the full original VII105.9 statement and its explicit U-interior conclusion. They do not assume pure compactness, original orthogonality closedness, frame completion, global common intersections or the separate positive-extension theorem VII105.4. No assertion of physical realization or reconstruction is made."))),DescribeRole.Theorem),
                Paragraph(Text("Application to original state spectrality. Keep the same nonzero finite dimensional real V, entire closed pointed generating C and strictly positive original u. Put K=C intersect {u=1} and P=ext(K). EB means that for every p in ALL P, the ENTIRE full-effect exclusion D_p is the image of a complete Euclidean closed unit ball under an injective affine chart a of positive finite dimension. The dimension may vary with p, and every such chart is permitted. Throughout this application W means weakPair under EB: whenever an original proper effect distinguishes pure p,q, their whole minimal cone-face base H(p,q) is proper. No PSD or EJA model, common-center G, closedness of P, injectivity of the exclusion labels, or spectral conclusion is an additional premise.")),
                Paragraph(Text("A finite original mathematical frame consists of distinct points q_i in ALL P and real-linear effects b_i on ALL V, nonnegative on ALL C, with sum_i b_i=u and b_i(q_j)=delta_ij. Positivity and this same-unit identity imply b_i<=u on every cone vector by Finset.single_le_sum; hence these are precisely effects in the original full interval. A state spectrum is x=sum_i w_i q_i with w_i>=0 and sum_i w_i=1 in such a frame, for an arbitrary finite index set. Zero weights remain allowed, together with their outcomes and effects. No finite menu or instrument is asserted. This is normalized-state spectrality in Barnum and Hilgert, Definition 3.4, with Omega=K and their affine effects identified with the restrictions of the original [0,u]. It is distinct from uniqueness of spectral coefficients, strong symmetry and physical realizability.")),
                Paragraph(Text("The base and cone correspondence uses "), Ref("D5/S3/Quantum/Foundation/CircuitBalancedConfirmation.base_compact"), Text(", "), Ref("D5/S3/Quantum/Foundation/CircuitBalancedConfirmation.base_convex"), Text(", "), Ref("D5/S3/Quantum/Foundation/CircuitBalancedConfirmation.pure_mem"), Text(", "), Ref("D5/S3/Quantum/Foundation/CircuitBalancedConfirmation.pure_span"), Text(" and "), Ref("D5/S3/Quantum/Foundation/CircuitBalancedConfirmation.cone_bound"), Text(". They supply compact convex K, membership and spanning by all original pure points, and extension of pure-point bounds to the entire original cone. Linear and affine normalization leave the original unit and effect interval unchanged.")),
                Paragraph(Text("For the forward direction under W, exclusion_injective derives injectivity of p to D_p. Apply the original pure-point/exclusion-ball covering consequence of compact convex support geometry and the complete face classifier: every x in K has x=l p+(1-l)y, with p in P, y in D_p and 0<=l<=1. In an entire chart, write y=t q+(1-t)r along a diameter, where q,r are original pure endpoints, q+r=2a(0) and 0<=t<=1. At the ball center choose any unit direction, which exists because the chart dimension is positive. The covering geometry also includes pure and boundary x. Its affine-diameter existence belongs to classical convex geometry; this application uses its original-cone correspondence, without adding a new existence principle.")),
                Paragraph(Text("The covering correspondence uses the full zero-face classification "), Ref("D5/S3/Quantum/Foundation/FixedZeroObstruction.full_zero_faces"), Text(", the exposure and proper-face classification "), Ref("D5/S3/Quantum/Foundation/ExclusionBallFaces.exclusion_ball_faces"), Text(", the maximal-face equality "), Ref("D5/S3/Quantum/Foundation/ExclusionBallFaces.chart_face_eq"), Text(", and the boundary coverage "), Ref("D5/S3/Quantum/Foundation/MixedExclusionGeometry.frontier_covered"), Text(". In the support-chord case an original effect has complementary zero and one faces. If its zero face is not a pure singleton, it is D_s; every pure point of the one face has the same exclusion, so derived injectivity makes that face the singleton s. Compact-face extreme-point generation gives the full face equality. Thus at least one support endpoint is pure. This states the parameter interface needed for the spectral application; the separate geometric covering exposition treats the support construction itself.")),
                Paragraph(Text("Now apply "), Ref("D5/S3/Quantum/Foundation/OrthogonalJointCompletion.whole_joint_completion"), Text(" to the original orthogonal pair p,q. It supplies a third original pure point s in D_p, distinguishable from q. The existing orthogonal_center_sum argument gives q+s=2a(0), so s=r. Choose common exposing effects a_p,a_q from exclusion_ball_faces. The same joint-completion result supplies a_r=u-a_p-a_q, proper on ALL C, all nine delta readings and the linear-map identity a_p+a_q+a_r=u. Consequently p,q,r with these original effects form one complete three-outcome frame, and x has weights l,(1-l)t,(1-l)(1-t). All three weights are nonnegative and sum to one, including every endpoint and zero-weight case. No joint-budget or positive-extension premise is inserted.")),
                Paragraph(Text("The same construction decomposes every c in the ENTIRE cone C. For c nonzero, strict positivity gives u(c)>0; apply the state construction to c/u(c) and multiply each weight by u(c). The coefficients then sum to the original mass u(c) and their vector sum is c. For c=0, pure_span and nontriviality supply a pure point; whole_joint_completion supplies its complete three-outcome frame, and all three coefficients are zero. The zero vector and zero coefficients therefore require no extra frame assumption.")),
                Paragraph(Text("The reverse direction starts with any finite original frame spectrum of the specified y=(3a(v)+a(-v))/4=a(v/2), for a unit vector v in ANY complete chart at ANY p. By "), Ref("D5/S3/Quantum/Foundation/ExclusionBallFaces.exclusion_ball_faces"), Text(", D_p is the zero set in K of one actual original nonnegative exposing effect. Apply it to the entire finite vector sum. Finset.sum_eq_zero_iff_of_nonneg makes every weighted reading zero; each positive-weight frame point therefore lies in that same D_p. "), Ref("D5/S3/Quantum/Foundation/OriginalFacePolarity.chart_boundary"), Text(" puts every such pure point on its unit sphere. Zero weights contribute zero and impose no extra face constraint; they have not been excluded from the spectrum definition.")),
                Paragraph(Text("For distinct positive-weight indices, their existing global frame effect reads one and zero at the corresponding sphere points. Pull its complement u-b_i back along the whole chart. "), Ref("D5/S3/Quantum/Foundation/WholePairBallConfirmation.affine_zero_antipode"), Text(" gives the affine expression determined by its zero at one unit endpoint. The original bounds 0<=u-b_i<=1 on the ENTIRE ball and its value one at the other endpoint force the inner product of the two opposite unit directions to be one. The pinned Mathlib real_inner_le_norm and inner_eq_one_iff_of_norm_eq_one identify the second endpoint as the antipode of the first. This is the same support-equality argument used by orthogonal_center_sum; it requires neither W nor a new effect extension.")),
                Paragraph(Text("Choose one positive-weight index i, which exists because sum_i w_i=1. Every other positive-weight chart coordinate is -s_i. Affine preservation of the actual weighted sum, as in the pinned Mathlib map_affineCombination, gives (2w_i-1)s_i=v/2. Norms yield abs(2w_i-1)=1/2 and hence s_i=v or s_i=-v. A second positive-weight index must exist: otherwise w_i=1 contradicts that norm equality. Its coordinate is the opposite endpoint. According to the sign, the frame effect at i or at this second index distinguishes the ORIGINALLY SPECIFIED a(v),a(-v). Thus ANY finite spectrum of this particular biased state forces the original antipodal effect relation. The argument retains arbitrary finite outcome counts and all zero terms; it does not presuppose a two-outcome decomposition.")),
                Paragraph(Text("It follows on the full original EB domain that four conditions are equivalent: W; every x in K has a finite original-frame spectrum; every nonpure x in the relative boundary of K has such a spectrum; and every specified (3a(v)+a(-v))/4 has such a spectrum for every p, every complete positive-dimensional chart and every unit v. W gives the three-outcome construction above. Restriction gives all-state to nonpure-boundary spectrality. "), Ref("D5/S3/Quantum/Foundation/MixedExclusionGeometry.chart_intrinsic"), Text(" and "), Ref("D5/S3/Quantum/Foundation/MixedExclusionGeometry.exclusion_interior"), Text(" place a(v/2) in the relative interior of D_p and outside ALL P; "), Ref("D5/S3/Quantum/Foundation/MixedExclusionGeometry.exclusion_frontier"), Text(" places it on the relative boundary of K. This gives boundary to biased-state spectrality.")),
                Paragraph(Text("For the remaining implication, the finite-spectrum argument supplies ALL original antipodal distinctions. Given an original orthogonal pair p,q, chart_boundary supplies q's antipode r in D_p, also pure. The supplied distinction q perpendicular r, together with "), Ref("D5/S3/Quantum/Foundation/FacetZeroGluing.exclusion_symmetric"), Text(", puts both p and q in D_r. The original pair_le_face argument places their WHOLE minimal cone-face base H(p,q) inside this proper exclusion. Thus W is a conclusion. The private pair_le_face and orthogonal_center_sum facts are used here as parts of their existing owning proofs; this exposition does not make them new public interfaces. W keeps both its forward-construction and equivalence roles, and injectivity is used only after being derived from W.")),
                Paragraph(Text("More precisely, for any specified original chart direction with NO global proper effect distinguishing a(v) from a(-v), the vector y=(3a(v)+a(-v))/4 has all of the following properties simultaneously: it is in the relative interior of the ENTIRE D_p; it is in the relative boundary of the ENTIRE K; it is not original pure; it differs from that chart's center a(0); and it has NO finite original-frame spectrum. The first three properties follow from the chart-interior, nonpure-interior and exclusion-frontier identities above. Injectivity of a and v/2!=0 give the fourth. Any spectrum would force the missing original effect, giving the fifth. The exclusion covers every finite original mathematical frame, not just the displayed two-term mixture. Bias is essential to this argument: a center can have diameters in different directions, while y=a(v/2) fixes the specified one.")),
                Paragraph(Text("Conversely, if any original x in K lacks a finite spectrum, not all antipodes in all whole exclusion charts can be originally distinguishable: otherwise the preceding proper-face argument gives W and the all-state construction contradicts that failure. Hence some failed original direction exists and its specified biased state has every location, noncentrality, nonpurity and nonspectrality property just stated. This proves the conditional equivalence between existence of an original nonspectral state and existence of this exact kind of biased boundary witness. It does not exhibit a model satisfying the full background together with a failed antipodal direction. Such joint inhabitance remains open; the conditional equivalence supplies neither an inhabitant nor an impossibility proof.")),
                Paragraph(Text("The dependency correspondence uses the frozen cone, face, chart, symmetry, joint-completion and frame-sum results together with the pinned Mathlib finite-sum, affine and inner-product facts. It is an application of existing results, with no claim of new mathematical content or literature priority. The affine-diameter existence is attributed to the classical result cited by Barany, Hug and Schneider, Affine diameters of convex bodies, section 5, through Soltan's assertion 3.3. Barnum and Hilgert's classification requires strong symmetry in addition to their spectrality definition; no such classification theorem is invoked here. The broader EJA representation, spectral uniqueness and exact positive-support counts are not established by this application. Neither physical effects or instruments, resource availability, composite systems nor dynamics follow from these mathematical frames.")))));
    }
}
